// import { List } from '@chakra-ui/react'
// で使用する効果に必要なモノを定義。
// 基本的にChakra UIのモノをそのまま使用するので、Componentはラッパーしない
import type { ListRootProps, ListItemProps } from '@chakra-ui/react'


// <List.Root as='ol'>で listStyle(cssのlist-style-type)は "none"(デフォルト値)とする必要がある
export const olBracketsStyle = {
    counterIncrement: 'number',
    _marker: {
      content: '"(" counter(number) ")"'
    }
  } as ListItemProps;

export const olStart = (value: number) => {
  // List.RootのasはElementType | undefined型ですが、普通に'ol'とするとstring型として扱われる。
  // List.Rootのプロパティとなる構造体なので、すべてをListRootProps型として明示する。
  return {
    as: 'ol',
    counterReset: `number ${value - 1}`
  } as ListRootProps;
}
